-- CrismaQuest canonical saint-card catalogue.
-- Generated from config/crismaquest/saints.json. Safe and idempotent.

ON DUPLICATE KEY UPDATE
  slug=VALUES(slug),
  name=VALUES(name),
  category=VALUES(category),
  short_bio=VALUES(short_bio),
  feast_date=VALUES(feast_date),
  short_teaching=VALUES(short_teaching),
  image_path=VALUES(image_path),
  image_license=VALUES(image_license),
  active=1;

SELECT id, 'normal', NULL, 100, 1
FROM cq_saint_cards
WHERE card_number BETWEEN 1 AND 40
ON DUPLICATE KEY UPDATE chance_weight=100, active=1;
